package org.achievementlabs.mobile;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.nio.file.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;
public class CoreTests {
 @Test public void androidUpdaterIgnoresOtherPlatformsAndUntrustedDownloads()throws Exception{
  assertEquals("https://github.com/thevampirebat/achievement-labs",Updater.REPOSITORY);
  assertEquals("https://api.github.com/repos/thevampirebat/achievement-labs/releases?per_page=100",Updater.RELEASES_API);
  assertEquals("https://raw.githubusercontent.com/Achievement-Labs/achievement-labs/mobile-event-feed/catalogue.json",SessionEngine.EVENT_FEED);
  String page="https://github.com/thevampirebat/achievement-labs/releases/tag/android-v0.3.0";
  String download="https://github.com/thevampirebat/achievement-labs/releases/download/android-v0.3.0/AchievementLabs-Android-0.3.0.apk";
  JSONObject asset=new JSONObject().put("name","AchievementLabs-Android-0.3.0.apk").put("browser_download_url",download).put("size",100).put("digest","sha256:"+"a".repeat(64));
  JSONObject release=new JSONObject().put("html_url",page).put("assets",new JSONArray().put(asset));
  assertEquals("0.3.0",Updater.choose(new JSONArray().put(release)).getString("version"));
  asset.put("browser_download_url",download.replace("thevampirebat/achievement-labs","Achievement-Labs/achievement-labs"));assertNull(Updater.choose(new JSONArray().put(release)));
  asset.put("browser_download_url","https://example.com/other.apk");assertNull(Updater.choose(new JSONArray().put(release)));
  asset.put("browser_download_url",download).put("name","AchievementLabs-Windows.exe");assertNull(Updater.choose(new JSONArray().put(release)));
  asset.put("name","AchievementLabs-Android-0.3.0.apk");release.put("draft",true);assertNull(Updater.choose(new JSONArray().put(release)));
 }

 @Test public void finalAchievementPageNeverRequestsLiteralNull()throws Exception{
  assertEquals("",Net.nextPage(null));assertEquals("",Net.nextPage(new JSONObject()));
  JSONObject androidNull=new JSONObject(){@Override public String optString(String key){return "null";}};
  androidNull.put("continuationToken",JSONObject.NULL);
  assertEquals("",Net.nextPage(androidNull));
  assertEquals("",Net.nextPage(new JSONObject().put("continuationToken","null")));
  assertEquals("",Net.nextPage(new JSONObject().put("continuationToken","")));
  assertEquals("page+two/=",Net.nextPage(new JSONObject().put("continuationToken","page+two/=")));
  try{Net.nextPage(new JSONObject().put("continuationToken",17));fail();}catch(Exception expected){}
 }

 @Test public void pausedRequestMustFinishBeforeResumeAndCancelledStartDoesNotBlock()throws Exception{Core.SessionGate g=new Core.SessionGate();long first=g.start();assertTrue(g.begin(first));g.pause();assertTrue(g.finishing());try{g.start();fail();}catch(Exception expected){}g.finish(first);long next=g.start();g.pause();assertFalse(g.begin(next));assertFalse(g.busy());long finalRun=g.start();assertTrue(g.begin(finalRun));assertTrue(g.running(finalRun));g.finish(finalRun);assertFalse(g.busy());}
 @Test public void sessionsRejectAccountSwitches()throws Exception{Core.sameOwner("42","42");try{Core.sameOwner("42","43");fail();}catch(InterruptedException expected){}try{Core.sameOwner("","42");fail();}catch(InterruptedException expected){}}
 @Test public void requirementIdsSelectEventRouteRatherThanProgressValue()throws Exception{assertTrue(Core.eventRequirements(new JSONArray("[{\"id\":\"12345678-1111-2222-3333-444444444444\",\"current\":\"0\"}]")));assertFalse(Core.eventRequirements(new JSONArray("[{\"id\":\"00000000-0000-0000-0000-000000000000\",\"current\":null}]")));assertFalse(Core.eventRequirements(null));}
 @Test public void eventPacketsAndCollectorRejectInvalidAcknowledgements()throws Exception{String template="{\"data\":{\"baseData\":{\"titleId\":\"7\",\"serviceConfigId\":\"00000000-0000-0000-0000-000000000001\",\"id\":REPLACEID,\"xuid\":\"REPLACEXUID\",\"time\":\"REPLACETIME\"}}}";JSONArray recipe=new JSONArray("[[{\"target\":\"REPLACEID\",\"value\":\"2\"}]]");String body=Core.payloads(template,recipe,"7","42",100000).get(0);assertEquals(2,new JSONObject(body).getJSONObject("data").getJSONObject("baseData").getInt("id"));try{Core.payloads(template,recipe,"8","42",100);fail();}catch(Exception expected){}try{Core.collectorAck("{\"acc\":0}");fail();}catch(Exception expected){}try{Core.collectorAck("{\"efi\":{\"1\":[1]}}");fail();}catch(Exception expected){}Core.collectorAck("{\"acc\":1,\"rej\":0}");}
 @Test public void encryptedPCTransferAndQRCompatibility()throws Exception{byte[] key=new byte[32],nonce=new byte[12];for(int i=0;i<32;i++)key[i]=(byte)i;for(int i=0;i<12;i++)nonce[i]=(byte)i;JSONObject clear=new JSONObject().put("schemaVersion",1).put("xuid","42").put("kind","eventToken").put("authorization","").put("eventToken","x:XBL3.0 x=123;synthetic").put("expiresAt",700);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));c.updateAAD(Core.utf("AchievementLabs-PC-Transfer-v1"));byte[] cipher=c.doFinal(Core.utf(clear.toString()));JSONObject envelope=new JSONObject().put("schemaVersion",1).put("nonce",Core.b64(nonce)).put("ciphertext",Core.b64(Arrays.copyOf(cipher,cipher.length-16))).put("tag",Core.b64(Arrays.copyOfRange(cipher,cipher.length-16,cipher.length)));String pairing=Base64.getUrlEncoder().withoutPadding().encodeToString(key);JSONObject result=Core.openTransfer(Core.utf(envelope.toString()),pairing,100);assertTrue(Core.eventOnly(result));assertEquals("",result.getString("authorization"));try{Core.openTransfer(Core.utf(envelope.toString()),pairing,701);fail();}catch(Exception expected){}
  byte[] payload=Core.utf(new JSONObject().put("key",pairing).put("file",Core.b64(Core.utf(envelope.toString()))).toString());String data=Core.b64(payload),hash=Core.hash(payload);int middle=data.length()/2;Core.Collector collector=new Core.Collector();assertNull(collector.add("ALPC1|"+hash+"|1|2|"+data.substring(middle)));assertNull(collector.add("ALPC1|"+hash+"|1|2|"+data.substring(middle)));assertNotNull(collector.add("ALPC1|"+hash+"|0|2|"+data.substring(0,middle)));try{collector.add("ALPC1|"+"0".repeat(64)+"|0|2|AAAA");fail();}catch(Exception expected){}
 }
 @Test public void cSharpSwiftFixedVectorDecryptsOnJava()throws Exception{String json="{\"schemaVersion\":1,\"nonce\":\"AAECAwQFBgcICQoL\",\"ciphertext\":\"PCCleK2Ar3rbJOX42IYWT7nnqxaIDjYYGl3HsS9LLJBgZdqUwLN74hXQFoLmpRIathssvnTmg6ICphgqI5CMgIRUow66sgRNPjHcC4H7WodT76dATEErUqW/0v9WwJn19slr1Z8ysXTqdFvGIRYMGswCDN/B6Qf/NY8+v+eVL3qZaDf2hPvpMn2VIM5PszajQp2MW3Bp4yP+Ops2jvDTgOb78mg=\",\"tag\":\"zpeo91arlKCe4Kg2CWIRkA==\"}";assertEquals("42",Core.openTransfer(Core.utf(json),"AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8",100).getString("xuid"));}
 @Test public void realBundledCataloguePayloadsPassIdentityChecks()throws Exception{String root=System.getenv("LABS_CATALOGUE");assertNotNull(root);JSONObject index=new JSONObject(Core.text(Files.readAllBytes(Paths.get(root,"MobileIndex.json"))));int count=0;for(java.util.Iterator<String> titles=index.keys();titles.hasNext();){String title=titles.next();JSONObject entry=index.getJSONObject(title);if(!entry.isNull("reason"))continue;JSONObject recipes=new JSONObject(Core.text(Files.readAllBytes(Paths.get(root,"Events",title+".mapping.json")))).getJSONObject("recipes");String template=Core.text(Files.readAllBytes(Paths.get(root,"Events",title+".json")));for(java.util.Iterator<String> ids=recipes.keys();ids.hasNext();){String id=ids.next();assertFalse(Core.payloads(template,recipes.getJSONArray(id),title,"0",System.currentTimeMillis()).isEmpty());count++;}}assertTrue(count>16000);}
 @Test public void tokensVersionsAndSignatureConversion()throws Exception{assertEquals("XBL3.0 x=123;synthetic",Core.token("x:XBL3.0 x=123;synthetic",false));assertTrue(Core.newer("0.10.0","0.9.0"));assertFalse(Core.newer("1.0.0","2.0.0"));java.security.KeyPairGenerator g=java.security.KeyPairGenerator.getInstance("EC");g.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));java.security.KeyPair k=g.generateKeyPair();java.security.Signature s=java.security.Signature.getInstance("SHA256withECDSA");s.initSign(k.getPrivate());s.update(Core.utf("synthetic"));byte[] raw=OAuth.rawSignature(s.sign());assertEquals(64,raw.length);}
}
